import Foundation
import MongoKitten

/// A document of the "customers" collection. A property stays nil until it is set or read.
public struct Customer: Sendable, Equatable {
    public var id: String?
    public var email: String?
    public var name: String?
    public var age: Int?
    public var balance: Decimal?
    public var visits: Int?
    public var rate: Double?
    public var active: Bool?
    public var address: Customer.Address?
    public var tags: [String]?
    public var seen: Date?
    public var ref: UUID?
    public var photo: Data?
    public var scores: BsonValue?
    public var mixed: BsonValue?
    public var nothing: BsonValue?
    public var empty: [BsonValue]?
    public var deletedAt: Date?
    /// As it was read: a change writes only what differs
    var loadedDocument = Loaded()

    public init(id: String? = nil, email: String? = nil, name: String? = nil, age: Int? = nil, balance: Decimal? = nil, visits: Int? = nil, rate: Double? = nil, active: Bool? = nil, address: Customer.Address? = nil, tags: [String]? = nil, seen: Date? = nil, ref: UUID? = nil, photo: Data? = nil, scores: BsonValue? = nil, mixed: BsonValue? = nil, nothing: BsonValue? = nil, empty: [BsonValue]? = nil, deletedAt: Date? = nil) {
        self.id = id
        self.email = email
        self.name = name
        self.age = age
        self.balance = balance
        self.visits = visits
        self.rate = rate
        self.active = active
        self.address = address
        self.tags = tags
        self.seen = seen
        self.ref = ref
        self.photo = photo
        self.scores = scores
        self.mixed = mixed
        self.nothing = nothing
        self.empty = empty
        self.deletedAt = deletedAt
    }

    /// A nested document: it is stored with the one that holds it.
    public struct Address: Sendable, Equatable {
        public var street: String?
        public var city: String?
        public var zipCode: String?

        public init(street: String? = nil, city: String? = nil, zipCode: String? = nil) {
            self.street = street
            self.city = city
            self.zipCode = zipCode
        }
    }
}

extension Customer: DocumentValue {
    /// What a document holds.
    static func from(_ document: BsonDocument) throws -> Customer {
        var entity = Customer(
            id: try Bson.read(document, "_id", Bson.asObjectId),
            email: try Bson.read(document, "email", Bson.asText),
            name: try Bson.read(document, "name", Bson.asText),
            age: try Bson.read(document, "age", Bson.asInt64),
            balance: try Bson.read(document, "balance", Bson.asDecimal),
            visits: try Bson.read(document, "visits", Bson.asInt64),
            rate: try Bson.read(document, "rate", Bson.asDouble),
            active: try Bson.read(document, "active", Bson.asBool),
            address: try Bson.read(document, "address", Bson.asNested(Customer.Address.self)),
            tags: try Bson.read(document, "tags", Bson.asList(Bson.asText)),
            seen: try Bson.read(document, "seen", Bson.asDate),
            ref: try Bson.read(document, "ref", Bson.asUUID),
            photo: try Bson.read(document, "photo", Bson.asData),
            scores: try Bson.read(document, "scores", Bson.asAny),
            mixed: try Bson.read(document, "mixed", Bson.asAny),
            nothing: try Bson.read(document, "nothing", Bson.asAny),
            empty: try Bson.read(document, "empty", Bson.asList(Bson.asAny)),
            deletedAt: try Bson.read(document, "deletedAt", Bson.asDate))
        entity.loadedDocument = Loaded(document: try entity.toDocument())
        return entity
    }

    /// Its document: what is nil is left out.
    func toDocument() throws -> BsonDocument {
        var document: BsonDocument = [:]
        try Bson.write(&document, "_id", self.id, Bson.ofObjectId)
        try Bson.write(&document, "email", self.email, Bson.ofText)
        try Bson.write(&document, "name", self.name, Bson.ofText)
        try Bson.write(&document, "age", self.age, Bson.ofInt64)
        try Bson.write(&document, "balance", self.balance, Bson.ofDecimal)
        try Bson.write(&document, "visits", self.visits, Bson.ofInt64)
        try Bson.write(&document, "rate", self.rate, Bson.ofDouble)
        try Bson.write(&document, "active", self.active, Bson.ofBool)
        try Bson.write(&document, "address", self.address, Bson.ofNested)
        try Bson.write(&document, "tags", self.tags, Bson.ofList(Bson.ofText))
        try Bson.write(&document, "seen", self.seen, Bson.ofDate)
        try Bson.write(&document, "ref", self.ref, Bson.ofUUID)
        try Bson.write(&document, "photo", self.photo, Bson.ofData)
        try Bson.write(&document, "scores", self.scores, Bson.ofAny)
        try Bson.write(&document, "mixed", self.mixed, Bson.ofAny)
        try Bson.write(&document, "nothing", self.nothing, Bson.ofAny)
        try Bson.write(&document, "empty", self.empty, Bson.ofList(Bson.ofAny))
        try Bson.write(&document, "deletedAt", self.deletedAt, Bson.ofDate)
        return document
    }
}

extension Customer.Address: DocumentValue {
    /// What a document holds.
    static func from(_ document: BsonDocument) throws -> Customer.Address {
        return Customer.Address(
            street: try Bson.read(document, "street", Bson.asText),
            city: try Bson.read(document, "city", Bson.asText),
            zipCode: try Bson.read(document, "zip code", Bson.asText))
    }

    /// Its document: what is nil is left out.
    func toDocument() throws -> BsonDocument {
        var document: BsonDocument = [:]
        try Bson.write(&document, "street", self.street, Bson.ofText)
        try Bson.write(&document, "city", self.city, Bson.ofText)
        try Bson.write(&document, "zip code", self.zipCode, Bson.ofText)
        return document
    }
}

import Foundation
import MongoKitten

/// A document of the "orders" collection. A property stays nil until it is set or read.
public struct Order: Sendable, Equatable {
    public var id: String?
    public var number: Int?
    public var customer: String?
    public var seller: String?
    public var lines: [Order.Line]?
    /// As it was read: a change writes only what differs
    var loadedDocument = Loaded()

    public init(id: String? = nil, number: Int? = nil, customer: String? = nil, seller: String? = nil, lines: [Order.Line]? = nil) {
        self.id = id
        self.number = number
        self.customer = customer
        self.seller = seller
        self.lines = lines
    }

    /// Gives an identifier to the documents of its lists that have none: MongoDB numbers only whole documents.
    mutating func identifyItems() {
        lines = lines?.map { item in var item = item; item.id = item.id ?? Bson.newId(); return item }
    }

    /// A nested document: it is stored with the one that holds it.
    public struct Line: Sendable, Equatable {
        public var id: String?
        public var product: Order.Line.Product?
        public var quantity: Int?
        public var note: String?

        public init(id: String? = nil, product: Order.Line.Product? = nil, quantity: Int? = nil, note: String? = nil) {
            self.id = id
            self.product = product
            self.quantity = quantity
            self.note = note
        }

        /// A nested document: it is stored with the one that holds it.
        public struct Product: Sendable, Equatable {
            public var sku: String?
            public var price: Decimal?

            public init(sku: String? = nil, price: Decimal? = nil) {
                self.sku = sku
                self.price = price
            }
        }
    }
}

extension Order: DocumentValue {
    /// What a document holds.
    static func from(_ document: BsonDocument) throws -> Order {
        var entity = Order(
            id: try Bson.read(document, "_id", Bson.asObjectId),
            number: try Bson.read(document, "number", Bson.asInt64),
            customer: try Bson.read(document, "customer", Bson.asObjectId),
            seller: try Bson.read(document, "seller", Bson.asObjectId),
            lines: try Bson.read(document, "lines", Bson.asList(Bson.asNested(Order.Line.self))))
        entity.loadedDocument = Loaded(document: try entity.toDocument())
        return entity
    }

    /// Its document: what is nil is left out.
    func toDocument() throws -> BsonDocument {
        var document: BsonDocument = [:]
        try Bson.write(&document, "_id", self.id, Bson.ofObjectId)
        try Bson.write(&document, "number", self.number, Bson.ofInt64)
        try Bson.write(&document, "customer", self.customer, Bson.ofObjectId)
        try Bson.write(&document, "seller", self.seller, Bson.ofObjectId)
        try Bson.write(&document, "lines", self.lines, Bson.ofList(Bson.ofNested))
        return document
    }
}

extension Order.Line: DocumentValue {
    /// What a document holds.
    static func from(_ document: BsonDocument) throws -> Order.Line {
        return Order.Line(
            id: try Bson.read(document, "_id", Bson.asObjectId),
            product: try Bson.read(document, "product", Bson.asNested(Order.Line.Product.self)),
            quantity: try Bson.read(document, "quantity", Bson.asInt64),
            note: try Bson.read(document, "note", Bson.asText))
    }

