import Foundation

/// Operations on customers. Repositories commit every write.
public struct CustomerService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Customer after checking it.
    @discardableResult
    public func createCustomer(_ customer: Customer) async throws -> Customer {
        let values = Values(email: customer.email.map(Optional.some), name: customer.name.map(Optional.some), age: customer.age.map(Optional.some), balance: customer.balance.map(Optional.some), visits: customer.visits.map(Optional.some), rate: customer.rate.map(Optional.some), active: customer.active.map(Optional.some), address: customer.address.map(Optional.some), tags: customer.tags.map(Optional.some), seen: customer.seen.map(Optional.some), ref: customer.ref.map(Optional.some), photo: customer.photo.map(Optional.some), scores: customer.scores.map(Optional.some), mixed: customer.mixed.map(Optional.some), nothing: customer.nothing.map(Optional.some), empty: customer.empty.map(Optional.some), deletedAt: customer.deletedAt.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Customer()
            applyValues(&entity, values)
            return try await uow.customers.insert(entity)
        }
    }

    /// The Customer with this key; notFound when there is none.
    public func getCustomer(_ id: String) async throws -> Customer {
        try await find(unitOfWork, id)
    }

    /// A page of customers, by primary key.
    public func listCustomers(offset: Int, limit: Int) async throws -> Page<Customer> {
        try await unitOfWork.customers.list(offset: offset, limit: limit)
    }

    /// Changes the given values of a Customer.
    @discardableResult
    public func updateCustomer(_ id: String, _ changes: CustomerChanges) async throws -> Customer {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await uow.customers.update(current)
        }
    }

    /// Marks a Customer as deleted (deletedAt); reads leave it out from then on.
    public func deleteCustomer(_ id: String) async throws {
        try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            if !(try await uow.orders.listByCustomer(current.id!)).isEmpty {
                throw DomainError.conflict(entity: "Customer", reason: "rows of orders still point to it", fields: ["orders"])
            }
            current.deletedAt = Date()
            try await uow.customers.update(current)
        }
    }

    /// Adds an item to tags.
    @discardableResult
    public func addTag(_ id: String, _ tag: String) async throws -> Customer {
        return try await unitOfWork.transaction { uow in
            _ = try await find(uow, id)
            guard let changed = try await uow.customers.addTag(id, tag) else {
                throw DomainError.notFound(entity: "Customer", key: "\(id)")
            }
            return changed
        }
    }

    /// Removes an item from tags, by its value.
    @discardableResult
    public func removeTag(_ id: String, _ tag: String) async throws -> Customer {
        return try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if !(current.tags ?? []).contains(tag) {
                throw DomainError.notFound(entity: "Tag", key: "\(tag)")
            }
            guard let changed = try await uow.customers.removeTag(id, tag) else {
