    public func createOrder(_ order: Order) async throws -> Order {
        let values = Values(number: order.number.map(Optional.some), customer: order.customer.map(Optional.some), seller: order.seller.map(Optional.some), lines: order.lines.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
