    }

    /// Changes the given values of a Order.
    @discardableResult
    public func updateOrder(_ id: String, _ changes: OrderChanges) async throws -> Order {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await uow.orders.update(current)
        }
    }

    /// Deletes a Order.
    public func deleteOrder(_ id: String) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
