    }

    /// Adds an item to lines.
    @discardableResult
    public func addLine(_ id: String, _ line: Order.Line) async throws -> Order {
        var errors: [FieldError] = []
        checkOrderLine(line, "lines", &errors)
        if !errors.isEmpty { throw DomainError.validationFailed(entity: "Order", errors: errors) }
        return try await unitOfWork.transaction { uow in
            _ = try await find(uow, id)
            guard let changed = try await uow.orders.addLine(id, line) else {
                throw DomainError.notFound(entity: "Order", key: "\(id)")
            }
            return changed
        }
    }

    /// Removes an item from lines, by its identifier.
    @discardableResult
    public func removeLine(_ id: String, _ lineId: String) async throws -> Order {
        return try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if !(current.lines ?? []).contains(where: { $0.id == lineId }) {
                throw DomainError.notFound(entity: "Line", key: "\(lineId)")
            }
            guard let changed = try await uow.orders.removeLine(id, lineId) else {
                throw DomainError.notFound(entity: "Order", key: "\(id)")
            }
